/* the diode envelope detector, computed: carrier period = 1, `cyc` carrier periods per message period, RC in carrier periods.
   v follows the rectified wave up (diode on) and decays as exp(-dt/RC) when the diode is off. Returns [t, envelope, rectified, v]. */
const CM_sim=(m,cyc,RCp,n,ncar)=>{let v=1+m,o=[];for(let i=0;i<=ncar*n;i++){const t=i/n,e=1+m*Math.cos(2*Math.PI*t/cyc),s=Math.max(0,e*Math.cos(2*Math.PI*t));v=Math.max(s,v*Math.exp(-1/(n*RCp)));o.push([t,e,s,v])}return o};
