function EXTRA(R,ICON){
 /* hook: the AM wave that arrives, and the three parts that find its envelope */
 ICON.cmHookWave=(x,y)=>{const p=[],e1=[],e2=[];for(let i=0;i<=600;i++){const t=i/600,e=1+0.6*Math.cos(2*Math.PI*1.5*t);p.push([20+340*t,92-34*e*Math.cos(2*Math.PI*24*t)]);e1.push([20+340*t,92-34*e]);e2.push([20+340*t,92+34*e])}
  return `<g transform="translate(${x-190} ${y-90})">${CM_box(0,0,380,180,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${CM_pl(p,BLU,2)}${CM_pl(e1,ORG,3,'stroke-dasharray="8 6"')}${CM_pl(e2,ORG,3,'stroke-dasharray="8 6"')}${CM_T(190,170,'1 MHz AM wave; dashed: the voice',{fs:20,fw:700,a:'middle',fill:CM_MUT})}</g>`};
 ICON.cmHookParts=(x,y)=>`<g transform="translate(${x-190} ${y-90})">${CM_box(0,0,380,180,{fill:'#FFFFFF',st:GRN,sw:3,r:18})}
  ${CM_L(30,60,110,60,INK,3)}<polygon points="110,44 110,76 138,60" fill="#FFFFFF" stroke="${INK}" stroke-width="3"/>${CM_L(140,44,140,76,INK,3.5)}${CM_L(140,60,350,60,INK,3)}
  ${CM_L(200,60,200,92,INK,3)}${CM_L(180,92,220,92,INK,3.5)}${CM_L(180,104,220,104,INK,3.5)}${CM_L(200,104,200,140,INK,3)}
  ${CM_L(290,60,290,80,INK,3)}<rect x="280" y="80" width="20" height="44" rx="2" fill="#FFFFFF" stroke="${INK}" stroke-width="3"/>${CM_L(290,124,290,140,INK,3)}${CM_L(30,140,350,140,INK,3)}
  ${CM_T(124,32,'diode',{fs:22,fw:800,a:'middle',fill:GRN})}${CM_T(234,104,'C',{fs:24,fw:800,fill:GRN})}${CM_T(310,108,'R',{fs:24,fw:800,fill:GRN})}${CM_T(190,170,'three parts, no chip',{fs:20,fw:700,a:'middle',fill:CM_MUT})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.cmDet=(x,y)=>{const d=CM_sim(0.6,20,3,24,20);return `<g transform="translate(${x-210} ${y-165})">${CM_pl(CM_map(d,2,0,420,250,90,20),CM_GRY,1.5)}${CM_pl(CM_map(d,1,0,420,250,90,20),GRN,2.5,'stroke-dasharray="8 6"')}${CM_pl(CM_map(d,3,0,420,250,90,20),BLU,4)}${CM_T(210,292,'output rides the peaks',{fs:24,fw:800,a:'middle',fill:BLU})}</g>`};
 ICON.cmCoh=(x,y)=>{const f=[],h=[];for(let i=0;i<=240;i++){const t=i/240*2,br=1+1.2*Math.cos(2*Math.PI*t);f.push([20+380*t/2,130-4*Math.abs(10*br)]);h.push([20+380*t/2,290-4*(5*br)])}
  return `<g transform="translate(${x-210} ${y-165})">${CM_L(20,130,400,130,CM_GRY,2)}${CM_pl(f,TRED,3.5)}${CM_T(410,36,'envelope: folded',{fs:22,fw:800,a:'end',fill:TRED})}${CM_L(20,290,400,290,CM_GRY,2)}${CM_pl(h,GRN,3.5)}${CM_T(410,200,'coherent: 5 + 6 cos',{fs:22,fw:800,a:'end',fill:GRN})}${CM_T(20,166,'m = 1.2',{fs:22,fw:700,fill:CM_MUT})}</g>`};
 ICON.cmTx=(x,y)=>{const bar=(xx,p,col,t,s)=>`<rect x="${xx}" y="${260-p*2.6}" width="130" height="${(p*2.6).toFixed(1)}" rx="10" fill="${col}" fill-opacity=".85"/>`+CM_T(xx+65,250-p*2.6,t,{fs:28,fw:800,a:'middle',fill:col})+CM_T(xx+65,294,s,{fs:22,fw:700,a:'middle',fill:CM_MUT});
  return `<g transform="translate(${x-210} ${y-165})">${CM_L(20,260,400,260,CM_GRY,2)}${bar(50,50,BLU,'50 %','low-level amp')}${bar(240,66.3,GRN,'66.3 %','high-level set')}</g>`};
}
